@require_http_methods(["DELETE"])
def terminate_db_cluster(request, cluster_id):
    cluster = get_object_or_404(ManagedDatabaseCluster, id=cluster_id, tenant=request.user.tenant)
    cluster.delete()
    return JsonResponse({'status': 'terminating'})

@receiver(pre_delete, sender=ManagedDatabaseCluster)
def teardown_cloud_rds(sender, instance, **kwargs):
    rds_client.delete_db_cluster(
        DBClusterIdentifier=instance.cloud_resource_id,
        SkipFinalSnapshot=True
    )
